export default function install(app){
 const key="nie-capacity-map-colour-mode",styleId="nie-capacity-complete-dark-theme",root=document.documentElement,body=document.body;
 document.getElementById(styleId)?.remove();
 const style=document.createElement("style");style.id=styleId;style.textContent=`
 .calcite-mode-dark #app-view .esri-widget,.calcite-mode-dark #app-view .esri-menu,.calcite-mode-dark #app-view [role="dialog"],.calcite-mode-dark #app-view [role="listbox"],.calcite-mode-dark #app-view [role="menu"],.calcite-mode-dark #app-view .esri-popup__main-container,.calcite-mode-dark #app-view .esri-popup__header,.calcite-mode-dark #app-view .esri-popup__content,.calcite-mode-dark #app-view .esri-popup__footer,.calcite-mode-dark #app-view .esri-popup__navigation,.calcite-mode-dark #app-view .esri-features,.calcite-mode-dark #app-view .esri-feature,.calcite-mode-dark #app-view .esri-feature__content-element{background-color:#20272c!important;color:#f4f6f7!important;border-color:#4a535a!important}
 .calcite-mode-dark #app-view [role="dialog"]>div,.calcite-mode-dark #app-view [role="dialog"] calcite-focus-trap,.calcite-mode-dark #app-view [role="dialog"] .esri-popup__header-container,.calcite-mode-dark #app-view [role="dialog"] .esri-features__container{background-color:#20272c!important;color:#f4f6f7!important;border-color:#4a535a!important}
 .calcite-mode-dark #app-view .esri-widget h1,.calcite-mode-dark #app-view .esri-widget h2,.calcite-mode-dark #app-view .esri-widget h3,.calcite-mode-dark #app-view .esri-widget p,.calcite-mode-dark #app-view .esri-widget strong,.calcite-mode-dark #app-view [role="dialog"] span:not([style*="background"]),.calcite-mode-dark #app-view .esri-popup__button,.calcite-mode-dark #app-view a{color:#f4f6f7!important;border-color:#4a535a!important}
 .calcite-mode-dark #app-view .esri-popup__pointer-direction,.calcite-mode-dark #app-view .esri-popup__pointer-direction-container,.calcite-mode-dark #app-view [role="presentation"]>div{background-color:#20272c!important}
 .calcite-mode-dark #app-view button[data-details]{background:#63b7e8!important;border-color:#63b7e8!important;color:#101619!important}
 .calcite-mode-dark #app-view input,.calcite-mode-dark #app-view select{background:#293238!important;color:#f4f6f7!important;border-color:#69737a!important}
 .calcite-mode-dark #app-view .esri-widget table,.calcite-mode-dark #app-view .esri-widget fieldset{border-color:#4a535a!important}
 `;document.head.append(style);
 const action=document.createElement("calcite-action");action.className="esri-widget";action.setAttribute("scale","m");
 const vars={"--calcite-color-foreground-1":"#20272c","--calcite-color-foreground-2":"#293238","--calcite-color-foreground-3":"#343e45","--calcite-color-text-1":"#f4f6f7","--calcite-color-text-2":"#d5dadd","--calcite-color-text-3":"#b6bec3","--calcite-color-border-1":"#69737a","--calcite-color-border-2":"#4a535a","--calcite-color-border-3":"#394249","--calcite-color-brand":"#63b7e8","--calcite-color-brand-hover":"#82c7ee","--calcite-color-brand-press":"#45a2d7","--arcgis-color-foreground-1":"#20272c","--arcgis-color-foreground-2":"#293238","--arcgis-color-text-1":"#f4f6f7","--arcgis-color-text-2":"#d5dadd","--arcgis-color-border-1":"#69737a","--arcgis-color-border-2":"#4a535a"};
 const selector="#app-view, #app-view arcgis-expand, #app-view arcgis-layer-list, #app-view arcgis-basemap-gallery, #app-view arcgis-search, #app-view arcgis-home, #app-view arcgis-scale-bar, #app-view calcite-action, #app-view calcite-button, #app-view calcite-input, #app-view calcite-chip, #app-view .esri-widget, #app-view [role='dialog'], #app-view [role='listbox'], #app-view [role='menu']";
 const themed=new Set();let dark=false;try{dark=localStorage.getItem(key)==="dark"}catch{}
 const themeElement=el=>{if(!(el instanceof HTMLElement))return;if(dark){el.classList.add("calcite-mode-dark","nie-dark-component");for(const [k,v] of Object.entries(vars))el.style.setProperty(k,v);themed.add(el)}else{el.classList.remove("calcite-mode-dark","nie-dark-component");for(const k of Object.keys(vars))el.style.removeProperty(k);themed.delete(el)}};
 const themeAll=()=>{document.querySelectorAll(selector).forEach(themeElement);const popup=app.view.popup?.container;if(popup instanceof HTMLElement)themeElement(popup)};
 const apply=()=>{root.classList.toggle("calcite-mode-dark",dark);body.classList.toggle("calcite-mode-dark",dark);root.style.colorScheme=dark?"dark":"light";body.style.colorScheme=dark?"dark":"light";action.setAttribute("icon",dark?"brightness":"moon");action.setAttribute("text",dark?"Use light mode":"Use dark mode");action.setAttribute("title",dark?"Use light mode":"Use dark mode");action.toggleAttribute("active",dark);if(!dark){for(const el of [...themed])themeElement(el)}themeAll();setTimeout(themeAll,0);try{localStorage.setItem(key,dark?"dark":"light")}catch{}};
 const toggle=()=>{dark=!dark;apply()};action.addEventListener("click",toggle);app.view.ui.add(action,"top-right");
 const observer=new MutationObserver(()=>themeAll());observer.observe(document.getElementById("app-view")||body,{childList:true,subtree:true});const popupHandle=app.view.watch("popup.visible",themeAll);apply();
 app.onCleanup(()=>{action.removeEventListener("click",toggle);app.view.ui.remove(action);action.remove();observer.disconnect();popupHandle?.remove?.();dark=false;for(const el of [...themed])themeElement(el);style.remove();root.classList.remove("calcite-mode-dark");body.classList.remove("calcite-mode-dark");root.style.colorScheme="";body.style.colorScheme=""});
 return{darkModeOption:true,themedComponents:["popup","layer list","basemap gallery","address search","home","scale bar","legend","prompt panel","map actions"],initialMode:dark?"dark":"light"}
}